import{_ as o,C as d,o as a,c as r,a3 as i,b as n,w as l,a as c,E as s,a4 as u}from"./chunks/framework.DACwFHq9.js";const g=JSON.parse('{"title":"Guided Flow 长交互容器与升级信息分层方案","description":"","frontmatter":{},"headers":[],"relativePath":"Plan/guided-flow-long-interaction-redesign.md","filePath":"Plan/guided-flow-long-interaction-redesign.md","lastUpdated":1785947010000}'),h={name:"Plan/guided-flow-long-interaction-redesign.md"};function p(E,e,f,b,A,B){const t=d("Mermaid");return a(),r("div",null,[e[1]||(e[1]=i('<h1 id="guided-flow-长交互容器与升级信息分层方案" tabindex="-1">Guided Flow 长交互容器与升级信息分层方案 <a class="header-anchor" href="#guided-flow-长交互容器与升级信息分层方案" aria-label="Permalink to &quot;Guided Flow 长交互容器与升级信息分层方案&quot;">​</a></h1><blockquote><p>状态：Phase A–C 已实现，待真实 Tauri / WebView 验收</p><p>创建日期：2026-08-03</p><p>修订日期：2026-08-05</p><p>关联文档：</p><ul><li><a href="./guided-flow-plan">Guided Flow 引导模块收口计划</a></li><li><a href="./../../src/tools/knowledge-base/docs/Plan/knowledge-base-guided-migration-refactor-plan">知识库迁移方式重构方案</a></li><li><a href="./v0.7.0-alpha.1-release-readiness-and-experience-plan">0.7.0-alpha.1 发布就绪与体验计划</a></li></ul><p>本文记录两项交互决策：</p><ol><li>长时间、多状态、多步骤的迁移交互不再继续复用通用 <code>BaseDialog</code> 的外层几何；</li><li>版本说明与数据迁移任务在用户入口和可见流程上分开。</li></ol><p>本文不是对现有实现的逐行描述。实现前仍需以当前代码、现有领域状态和真实 Tauri 窗口行为为准。</p></blockquote><blockquote><p>实现记录（2026-08-05）：已新增 <code>GuidedFlowSurface</code>，完成主内容保持挂载但隐藏/<code>inert</code>、Shell 双栏布局、默认 footer 与 step-owned footer 互斥、迁移步骤单一滚动责任、独立版本说明阅读面板及通知 action 分发。前端类型检查与相关组件/流程测试已通过；真实 Tauri 几何与透明链路仍按第 8.2 节验收。</p></blockquote><h2 id="_1-结论摘要" tabindex="-1">1. 结论摘要 <a class="header-anchor" href="#_1-结论摘要" aria-label="Permalink to &quot;1. 结论摘要&quot;">​</a></h2><h3 id="_1-1-为长流程增加专用-surface" tabindex="-1">1.1 为长流程增加专用 Surface <a class="header-anchor" href="#_1-1-为长流程增加专用-surface" aria-label="Permalink to &quot;1.1 为长流程增加专用 Surface&quot;">​</a></h3><p>升级迁移引导使用专用的 <code>GuidedFlowSurface</code>（暂定名），而不是继续让 <code>BaseDialog</code> 同时承担通用弹窗和长流程容器的职责。</p><p>Surface 的重点是稳定的布局边界和清晰的退出语义，不是把普通弹窗简单放大：</p><ul><li>Surface 固定在标题栏以下，占满剩余应用视口；</li><li>标题栏继续保留，不隐藏、不销毁 <code>MainLayout</code>；</li><li>Guided Flow 激活时，只隐藏标题栏以下的主界面内容区，包括 Sidebar 和主要内容区域；</li><li>主界面内容保持挂载，关闭 Flow 后恢复原来的路由和页面状态；</li><li>Surface 使用主题系统已有的半透明背景和模糊效果，使窗口外的桌面背景成为视觉底层；</li><li>背后的业务 UI 不应透过 Surface 继续可见或可交互；</li><li>步骤切换只替换流程内容，不重新创建外层 Surface，不做高度自适应动画；</li><li>迁移执行、失败、重试和恢复继续使用同一个流程容器。</li></ul><p>动画不是本方案的目标。若保留进入/退出动画，也只能是非必要的轻量效果，并且不能影响布局稳定性、焦点和退出控制。本方案不对性能收益作承诺。</p><h3 id="_1-2-版本说明与迁移任务分开" tabindex="-1">1.2 版本说明与迁移任务分开 <a class="header-anchor" href="#_1-2-版本说明与迁移任务分开" aria-label="Permalink to &quot;1.2 版本说明与迁移任务分开&quot;">​</a></h3><p>版本说明是阅读信息，迁移引导是需要用户确认和执行的任务。两者可以共享版本检测结果，但不共享同一个必须连续完成的可见流程：</p><ul><li>版本说明可以从通知中心、关于页等入口单独打开；</li><li>迁移事项只有在确实存在待处理贡献项时才进入 Guided Flow；</li><li>阅读或关闭版本说明不等于迁移完成；</li><li>迁移完成也不应强迫用户重新阅读整篇版本说明；</li><li>如果版本说明和迁移事项同时存在，不连续强制弹出两个阅读/任务弹窗。</li></ul><p>版本说明阅读面板是否复用 Guided Flow runtime，可以在实现时单独决定；产品语义上必须保持只读，不修改迁移状态。</p><h3 id="_1-3-验收重点" tabindex="-1">1.3 验收重点 <a class="header-anchor" href="#_1-3-验收重点" aria-label="Permalink to &quot;1.3 验收重点&quot;">​</a></h3><p>验收不以“动画是否顺滑”为重点，而关注：</p><ol><li>标题栏仍然可见，Surface 正确位于标题栏下方；</li><li>Sidebar 和主内容区域被隐藏且不能获得交互焦点；</li><li>Surface 外层位置和尺寸不随步骤内容变化；</li><li>每个交互表面只有一个明确的滚动责任人；</li><li>迁移执行期间的关闭、稍后处理、失败和恢复语义与现有领域状态一致；</li><li>版本说明阅读不会误改迁移状态。</li></ol><h2 id="_2-当前实现与问题边界" tabindex="-1">2. 当前实现与问题边界 <a class="header-anchor" href="#_2-当前实现与问题边界" aria-label="Permalink to &quot;2. 当前实现与问题边界&quot;">​</a></h2><h3 id="_2-1-当前组件关系" tabindex="-1">2.1 当前组件关系 <a class="header-anchor" href="#_2-1-当前组件关系" aria-label="Permalink to &quot;2.1 当前组件关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>当前实现</th><th>本次处理</th></tr></thead><tbody><tr><td>主界面</td><td><code>MainLayout</code> 中包含 <code>TitleBar</code>、全局弹层和 <code>common-layout</code></td><td>保持 <code>MainLayout</code> 挂载，只隐藏标题栏以下的主界面内容</td></tr><tr><td>外层流程</td><td><code>GuidedFlowModal.vue</code> 复用 <code>BaseDialog.vue</code></td><td>改为专用 Surface，迁移流程不再依赖普通弹窗的宽高和过渡</td></tr><tr><td>流程壳层</td><td><code>GuidedFlowShell.vue</code> 负责 header、步骤信息、内容和 footer</td><td>保留流程运行时能力，重新明确 Surface、Shell、步骤的布局责任</td></tr><tr><td>迁移步骤</td><td><code>MigrationStep.vue</code> 自己管理迁移子阶段、内容滚动和 step-owned footer</td><td>保留领域操作；需要收紧滚动和 footer 契约</td></tr><tr><td>升级说明</td><td><code>UpgradeSummaryStep</code> 中包含版本说明展示</td><td>拆出只读阅读入口，迁移概览只引用与任务相关的提示</td></tr><tr><td>通知中心</td><td>已有持久化通知和 <code>metadata</code></td><td>后续补充版本说明 action；本次不顺带重写通知系统</td></tr></tbody></table><h3 id="_2-2-本次不解决的问题" tabindex="-1">2.2 本次不解决的问题 <a class="header-anchor" href="#_2-2-本次不解决的问题" aria-label="Permalink to &quot;2.2 本次不解决的问题&quot;">​</a></h3><p>以下问题如果没有现有代码或产品需求支撑，不在本方案中新增：</p><ul><li>不新增独立 Tauri 原生窗口；</li><li>不为了容器改造重写 Guided Flow Manager 的持久化模型；</li><li>不新增 <code>interrupted</code> 等迁移执行状态；</li><li>不把所有模块都改成长交互容器；</li><li>不建设完整的升级中心页面；</li><li>不把通知去重、版本确认和历史版本合并扩展成独立的大型项目；</li><li>不以“透出壁纸”推导性能收益；</li><li>不通过禁止滚动或固定页面高度掩盖内部布局问题。</li></ul><p>如果后续需要可靠支持进程崩溃、断电或任务管理器强杀后的迁移恢复，应另行设计迁移执行日志、检查点和幂等恢复机制，不能假设 Surface 自身可以完成这件事。</p><h2 id="_3-信息架构" tabindex="-1">3. 信息架构 <a class="header-anchor" href="#_3-信息架构" aria-label="Permalink to &quot;3. 信息架构&quot;">​</a></h2>',24)),(a(),n(u,null,{default:l(()=>[s(t,{id:"mermaid-331",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%E5%BA%94%E7%94%A8%E5%90%AF%E5%8A%A8%20%2F%20%E6%A3%80%E6%9F%A5%E6%9B%B4%E6%96%B0%5D%20--%3E%20B%7B%E6%A3%80%E6%B5%8B%E7%BB%93%E6%9E%9C%7D%0A%20%20B%20--%3E%7C%E6%9C%89%E7%89%88%E6%9C%AC%E8%AF%B4%E6%98%8E%7C%20C%5B%E9%80%9A%E7%9F%A5%E4%B8%AD%E5%BF%83%EF%BC%9A%E6%9B%B4%E6%96%B0%E6%91%98%E8%A6%81%5D%0A%20%20C%20--%3E%20D%5B%E7%8B%AC%E7%AB%8B%E7%89%88%E6%9C%AC%E8%AF%B4%E6%98%8E%E9%98%85%E8%AF%BB%E9%9D%A2%E6%9D%BF%5D%0A%20%20B%20--%3E%7C%E6%9C%89%E5%BE%85%E5%A4%84%E7%90%86%E8%BF%81%E7%A7%BB%7C%20E%5BGuided%20Flow%20%E9%95%BF%E6%B5%81%E7%A8%8B%20Surface%5D%0A%20%20B%20--%3E%7C%E4%B8%A4%E8%80%85%E9%83%BD%E6%9C%89%7C%20C%0A%20%20B%20--%3E%7C%E4%B8%A4%E8%80%85%E9%83%BD%E6%9C%89%7C%20E%0A%20%20F%5B%E8%AE%BE%E7%BD%AE%20%E2%86%92%20%E5%85%B3%E4%BA%8E%5D%20--%3E%20D%0A%20%20G%5B%E8%AE%BE%E7%BD%AE%20%2F%20%E7%9F%A5%E8%AF%86%E5%BA%93%E6%81%A2%E5%A4%8D%E5%85%A5%E5%8F%A3%5D%20--%3E%20E%0A%20%20E%20--%3E%20H%7B%E8%BF%81%E7%A7%BB%E7%BB%88%E6%80%81%7D%0A%20%20H%20--%3E%7C%E5%AE%8C%E6%88%90%7C%20I%5B%E8%AE%B0%E5%BD%95%E8%B4%A1%E7%8C%AE%E9%A1%B9%E5%AE%8C%E6%88%90%5D%0A%20%20H%20--%3E%7C%E7%A8%8D%E5%90%8E%E5%A4%84%E7%90%86%7C%20J%5B%E4%BF%9D%E7%95%99%E5%8F%AF%E6%81%A2%E5%A4%8D%E7%8A%B6%E6%80%81%5D%0A%20%20H%20--%3E%7C%E5%A4%B1%E8%B4%A5%E6%88%96%E9%83%A8%E5%88%86%E5%AE%8C%E6%88%90%7C%20K%5B%E4%BF%9D%E7%95%99%E6%81%A2%E5%A4%8D%E4%B8%8E%E9%87%8D%E8%AF%95%E5%85%A5%E5%8F%A3%5D%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i(`<h3 id="_3-1-版本说明" tabindex="-1">3.1 版本说明 <a class="header-anchor" href="#_3-1-版本说明" aria-label="Permalink to &quot;3.1 版本说明&quot;">​</a></h3><p>版本说明分成三层，不从长文机械截断：</p><ol><li><strong>通知摘要</strong>：标题、版本、发布时间、简短摘要和重点；</li><li><strong>阅读面板</strong>：完整正文、重点列表和兼容提示；</li><li><strong>迁移提示</strong>：只在确实影响用户操作时，在迁移概览或具体步骤中引用相关内容。</li></ol><p>阅读面板可以关闭和重复打开。它只记录阅读相关行为，不调用贡献项完成回调，也不修改迁移 Flow 状态。</p><p>版本说明按每个版本记录，还是按一次升级批次合并，属于待确认的产品规则，不在本方案中默认决定。</p><h3 id="_3-2-迁移引导" tabindex="-1">3.2 迁移引导 <a class="header-anchor" href="#_3-2-迁移引导" aria-label="Permalink to &quot;3.2 迁移引导&quot;">​</a></h3><p>迁移引导只展示当前待处理事项。建议的外层流程是：</p><ol><li><code>overview</code>：说明检测到什么、影响什么、用户需要确认什么；</li><li><code>migration</code>：由贡献项提供领域步骤，内部可以有方案确认、执行、校验和清理等 UI 子阶段；</li><li><code>complete</code>：说明哪些工作已完成、哪些可选清理未执行，以及如何再次查看结果。</li></ol><p><code>plan</code>、<code>executing</code>、<code>verify</code>、清理展开状态等属于贡献项内部状态，不应被误写成新的外层 Guided Flow 步骤。具体哪些状态需要持久化，以领域实现为准。</p><h2 id="_4-guidedflowsurface-设计" tabindex="-1">4. GuidedFlowSurface 设计 <a class="header-anchor" href="#_4-guidedflowsurface-设计" aria-label="Permalink to &quot;4. GuidedFlowSurface 设计&quot;">​</a></h2><h3 id="_4-1-承载范围" tabindex="-1">4.1 承载范围 <a class="header-anchor" href="#_4-1-承载范围" aria-label="Permalink to &quot;4.1 承载范围&quot;">​</a></h3><p>Surface 使用 <code>position: fixed</code>，从标题栏底部开始覆盖：</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">top: var(--titlebar-height, 0px);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">left: 0;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">right: 0;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bottom: 0;</span></span></code></pre></div><p>实际实现应优先使用项目已有的标题栏高度变量和主题变量，不在业务组件中重复定义窗口几何。</p><p>Guided Flow 激活时的主界面处理：</p><ul><li><code>MainLayout</code> 保持挂载；</li><li><code>TitleBar</code> 保持可见；</li><li>隐藏 <code>MainLayout</code> 中标题栏以下的 <code>common-layout</code>，包括 Sidebar 和 <code>main-content</code>；</li><li>主界面内容不能获得鼠标、键盘或辅助技术焦点；</li><li>不使用 <code>v-if</code> 销毁路由页面，避免恢复时丢失页面状态；</li><li>其他位于 <code>MainLayout</code> 内的全局弹层需要有明确处理策略，不能意外浮在 Surface 上方。</li></ul><p>隐藏主界面的类名和状态来源可以由 <code>GuidedFlowHost</code> 或共享 store 提供，但不能通过组件名称含糊表达为“隐藏整个 <code>MainLayout</code>”。</p><h3 id="_4-2-视觉层" tabindex="-1">4.2 视觉层 <a class="header-anchor" href="#_4-2-视觉层" aria-label="Permalink to &quot;4.2 视觉层&quot;">​</a></h3><p>Surface 的视觉层遵循主题系统：</p><ul><li>使用主题提供的半透明容器背景；</li><li>使用 <code>backdrop-filter: blur(var(--ui-blur))</code> 或项目已有的毛玻璃封装；</li><li>背后业务 UI 已被隐藏，因此半透明层不应透出 Sidebar、页面卡片或业务文字；</li><li>透明链路需要在真实 Tauri 窗口中确认，包括窗口透明配置、<code>html/body/#app</code> 背景和标题栏以下容器背景；</li><li>文字、按钮、边框和错误提示必须满足当前主题下的可读性；</li><li>动画可有可无，不能成为布局和验收前提。</li></ul><h3 id="_4-3-布局" tabindex="-1">4.3 布局 <a class="header-anchor" href="#_4-3-布局" aria-label="Permalink to &quot;4.3 布局&quot;">​</a></h3><p>建议采用双栏布局，但双栏不是硬性视觉比例要求：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GuidedFlowSurface</span></span>
<span class="line"><span>└── GuidedFlowShell</span></span>
<span class="line"><span>    ├── header（标题、当前状态、关闭/稍后处理）</span></span>
<span class="line"><span>    └── body</span></span>
<span class="line"><span>        ├── rail（步骤大纲，可在窄窗口折叠或调整布局）</span></span>
<span class="line"><span>        └── main</span></span>
<span class="line"><span>            ├── content（当前步骤内容）</span></span>
<span class="line"><span>            └── footer（默认操作区，或由步骤接管）</span></span></code></pre></div><p>布局要求：</p><ul><li>Surface 外框在流程存活期间不随步骤内容变化；</li><li><code>body</code> 和主内容区域设置 <code>min-height: 0</code>，避免 flex 子项把外层撑高；</li><li>rail 不参与主内容高度测量；</li><li>步骤信息不能因为长标题、错误提示或日志展开而改变 Surface 外框；</li><li>窄窗口下需要有明确的 rail 降级方案，不能只固定为 25%–30% 宽度；</li><li>内容溢出应在内部边界处理，不能把滚动传递到 document 或窗口级页面。</li></ul><h3 id="_4-4-滚动和-footer-契约" tabindex="-1">4.4 滚动和 footer 契约 <a class="header-anchor" href="#_4-4-滚动和-footer-契约" aria-label="Permalink to &quot;4.4 滚动和 footer 契约&quot;">​</a></h3><p>必须明确每一种布局模式的滚动责任，避免出现嵌套滚动容器：</p><ul><li><strong>默认 footer 模式</strong>：Shell 的 <code>content</code> 负责滚动，footer 固定在内容区底部；</li><li><strong>step-owned footer 模式</strong>：步骤根节点填满 <code>main</code>，步骤自己提供 content 和 footer；Shell 不再同时提供外层滚动；</li><li>同一模式下不能同时让 Shell content 和步骤 body 都承担同一段内容的滚动；</li><li>日志终端、代码区域等确实需要独立滚动的局部区域可以例外，但必须有明确的高度边界和键盘滚动行为；</li><li>步骤切换后，新的主要 content 默认回到顶部；执行中的任务不得因父组件更新而丢失运行状态。</li></ul><p>当前 <code>MigrationStep</code> 已使用 step-owned footer 和内部 <code>.migration-body</code> 滚动，迁移改造时应先落实上述契约，再调整样式，不要只在外层继续叠加 <code>overflow</code> 规则。</p><h2 id="_5-退出和恢复语义" tabindex="-1">5. 退出和恢复语义 <a class="header-anchor" href="#_5-退出和恢复语义" aria-label="Permalink to &quot;5. 退出和恢复语义&quot;">​</a></h2><h3 id="_5-1-当前版本只约束用户交互" tabindex="-1">5.1 当前版本只约束用户交互 <a class="header-anchor" href="#_5-1-当前版本只约束用户交互" aria-label="Permalink to &quot;5.1 当前版本只约束用户交互&quot;">​</a></h3><p>Surface 需要根据当前 Flow 和贡献项状态决定可见操作，但不能只用全局 <code>busy</code> 推断领域安全性。至少要区分：</p><ul><li><strong>未开始确认</strong>：可以稍后处理；</li><li><strong>执行中</strong>：操作按钮禁用，不允许通过普通关闭绕过领域约束；</li><li><strong>失败或部分完成</strong>：可以关闭并保留恢复入口；</li><li><strong>完成待清理</strong>：清理是否可选由贡献项决定；</li><li><strong>完成</strong>：显示完成反馈并退出。</li></ul><p>“关闭”“稍后处理”“跳过”和“最小化”不是同义词，具体文案和是否存在由 Flow definition 与贡献项策略决定。对于当前知识库迁移，用户看到“稍后处理”应对应 <code>deferred</code>，不能用“跳过”掩盖实际语义。</p><h3 id="_5-2-系统窗口关闭" tabindex="-1">5.2 系统窗口关闭 <a class="header-anchor" href="#_5-2-系统窗口关闭" aria-label="Permalink to &quot;5.2 系统窗口关闭&quot;">​</a></h3><p>本次容器改造不承诺解决所有强制终止场景：</p><ul><li>自定义标题栏关闭、Alt+F4 和系统关闭事件是否需要拦截，应结合 <code>blockingScope</code> 和迁移领域能力实现；</li><li>突然崩溃、断电或进程强杀不能依赖前端事件记录状态；</li><li>如果未来要求中断后精确恢复，需要单独增加后端执行日志和检查点；</li><li>容器改造本身不得假设迁移已经具备幂等恢复能力。</li></ul><h3 id="_5-3-主界面恢复" tabindex="-1">5.3 主界面恢复 <a class="header-anchor" href="#_5-3-主界面恢复" aria-label="Permalink to &quot;5.3 主界面恢复&quot;">​</a></h3><p>关闭或完成 Surface 后：</p><ul><li>恢复标题栏以下主界面显示；</li><li>保持原路由和页面状态；</li><li>不因为 Surface 关闭而强制导航到固定页面；</li><li>如果有待恢复的迁移事项，由 Guided Flow 状态和入口决定下一次展示时机。</li></ul><h2 id="_6-状态边界" tabindex="-1">6. 状态边界 <a class="header-anchor" href="#_6-状态边界" aria-label="Permalink to &quot;6. 状态边界&quot;">​</a></h2><p>以下状态不能合并：</p><table tabindex="0"><thead><tr><th>状态</th><th>所属系统</th><th>含义</th><th>是否代表迁移完成</th></tr></thead><tbody><tr><td><code>notification.read</code></td><td>通知中心</td><td>用户看过通知摘要</td><td>否</td></tr><tr><td>release acknowledgement</td><td>应用生命周期</td><td>版本说明被确认、跳过或按产品规则处理</td><td>否</td></tr><tr><td>Guided Flow status</td><td>Guided Flow runtime</td><td>当前流程 pending、in-progress、deferred、failed 或 completed</td><td>不一定</td></tr><tr><td>contribution / migration status</td><td>升级贡献项和领域服务</td><td>迁移事项真实完成、部分完成或失败</td><td>是/否，按领域规则</td></tr></tbody></table><p>版本说明阅读面板不得调用 contribution 完成回调。迁移完成也不得被实现成“通知已读”的副作用。</p><p>Surface 的视觉改造不应隐式改变 Guided Flow definition version 或领域迁移版本。只有步骤定义、数据结构或恢复语义发生不兼容变化时，才需要另行设计版本升级和旧状态处理。</p><h2 id="_7-实现拆分建议" tabindex="-1">7. 实现拆分建议 <a class="header-anchor" href="#_7-实现拆分建议" aria-label="Permalink to &quot;7. 实现拆分建议&quot;">​</a></h2><h3 id="phase-a-建立-surface-边界-已实现" tabindex="-1">Phase A：建立 Surface 边界（已实现） <a class="header-anchor" href="#phase-a-建立-surface-边界-已实现" aria-label="Permalink to &quot;Phase A：建立 Surface 边界（已实现）&quot;">​</a></h3><ul><li>新增专用 <code>GuidedFlowSurface</code>；</li><li>保留 <code>MainLayout</code> 和 <code>TitleBar</code> 挂载；</li><li>仅隐藏标题栏以下的 <code>common-layout</code>；</li><li>迁移现有 <code>GuidedFlowModal</code> 的流程连接、层级和必要事件；</li><li>固定 header/body/main/footer 的布局边界；</li><li>建立默认 footer 与 step-owned footer 的互斥契约。</li></ul><h3 id="phase-b-收敛滚动和迁移步骤-已实现" tabindex="-1">Phase B：收敛滚动和迁移步骤（已实现） <a class="header-anchor" href="#phase-b-收敛滚动和迁移步骤-已实现" aria-label="Permalink to &quot;Phase B：收敛滚动和迁移步骤（已实现）&quot;">​</a></h3><ul><li>明确 <code>MigrationStep</code> 的 content、footer 和内部局部滚动责任；</li><li>保留现有迁移领域操作、报告和重试语义；</li><li>不在本阶段新增 <code>interrupted</code> 或新的后端恢复模型；</li><li>检查稍后处理、失败、部分完成、清理和关闭行为是否与现有状态一致。</li></ul><h3 id="phase-c-拆分版本说明入口-已实现" tabindex="-1">Phase C：拆分版本说明入口（已实现） <a class="header-anchor" href="#phase-c-拆分版本说明入口-已实现" aria-label="Permalink to &quot;Phase C：拆分版本说明入口（已实现）&quot;">​</a></h3><ul><li>增加独立的只读版本说明阅读面板；</li><li>关于页的“版本说明”打开阅读面板；</li><li>迁移入口只打开待处理的 Guided Flow；</li><li>通知中心 action 只负责打开对应版本说明或迁移入口，不直接调用迁移完成逻辑；</li><li>保持 notification read、release acknowledgement 和 contribution status 分离。</li></ul><h2 id="_8-验证门槛" tabindex="-1">8. 验证门槛 <a class="header-anchor" href="#_8-验证门槛" aria-label="Permalink to &quot;8. 验证门槛&quot;">​</a></h2><h3 id="_8-1-组件级" tabindex="-1">8.1 组件级 <a class="header-anchor" href="#_8-1-组件级" aria-label="Permalink to &quot;8.1 组件级&quot;">​</a></h3><p>至少验证：</p><ul><li>Guided Flow 激活时 <code>TitleBar</code> 仍然可见；</li><li>Sidebar 和主内容区域不可见、不可交互，且关闭后恢复；</li><li>Surface 外框不随步骤内容高度变化；</li><li>默认 footer 与 step-owned footer 不会同时出现；</li><li>每种布局模式只有一个主要滚动责任人；</li><li>错误提示、重试和日志展开不会撑大外层 Surface；</li><li><code>prefers-reduced-motion</code> 下不依赖动画完成状态；</li><li>版本说明阅读不改变迁移状态。</li></ul><h3 id="_8-2-真实-tauri-webview" tabindex="-1">8.2 真实 Tauri / WebView <a class="header-anchor" href="#_8-2-真实-tauri-webview" aria-label="Permalink to &quot;8.2 真实 Tauri / WebView&quot;">​</a></h3><p>必须至少验证：</p><table tabindex="0"><thead><tr><th>场景</th><th>通过标准</th></tr></thead><tbody><tr><td>打开迁移引导</td><td>标题栏仍可用，Surface 从标题栏下方开始，背后主界面不可见且不可交互</td></tr><tr><td>概览 → 迁移</td><td>外框不跳变，内容和 footer 边界稳定</td></tr><tr><td>迁移执行中</td><td>操作状态明确，普通关闭不会绕过领域约束</td></tr><tr><td>执行失败 → 重试</td><td>错误可读，重试可用，外框不被错误内容撑开</td></tr><tr><td>关闭后恢复</td><td>下次打开时使用现有 Guided Flow/领域状态恢复，不重复标记完成</td></tr><tr><td>通知 → 版本说明</td><td>只改变阅读相关状态，不标记迁移完成</td></tr><tr><td>低高度和窄宽度窗口</td><td>无裁切、无按钮溢出，rail 和内容有合理降级</td></tr></tbody></table><p>如果没有真实 Tauri 运行证据，只能说明“前端构建或组件测试通过”，不能说明“真实窗口体验已验证”。</p><h2 id="_9-已落地决策与待确认事项" tabindex="-1">9. 已落地决策与待确认事项 <a class="header-anchor" href="#_9-已落地决策与待确认事项" aria-label="Permalink to &quot;9. 已落地决策与待确认事项&quot;">​</a></h2><p>本轮实现已落地两项不新增领域状态的产品规则：</p><ol><li>版本说明沿用现有按版本记录的生命周期边界，每个版本生成一条包含 revision 的稳定键通知；同一版本同一 revision 不重复创建通知；</li><li>Guided Flow 活跃时迁移 Surface 层级高于版本说明阅读面板。主内容和通知抽屉均不能绕过当前迁移任务打开阅读面板。</li></ol><p>以下事项仍需结合后续领域需求确认：</p><ol><li><code>module</code> 级迁移是否允许用户继续操作其他模块；</li><li>系统窗口关闭和最小化在执行迁移期间的具体行为；</li><li>多个 contribution 是串行展示，还是先展示总览再逐个处理；</li><li>完成页是否保留为外层 Guided Flow 步骤。</li></ol><p>这些问题不影响当前 Surface、阅读面板和通知分层；后续实现仍不得在组件中自行发明新的持久化状态或恢复语义。</p>`,66))])}const m=o(h,[["render",p]]);export{g as __pageData,m as default};
